/**
 * ベトナムのクイズ(下書き・3問。うち1問は難易度9以上)。
 *
 * 難易度は他の盤面と同じ基準(1〜10、「その国の外にいる一般的な人が
 * どれくらい答えられそうか」)。都市カード(5件)が扱う具体的な事実
 * (ロンビエン橋の架橋会社・雲南線・ヒエンルオン橋の旗竿競争・
 * 雲の峠の開通年・統一会堂の門)はここでは問わない。
 *
 * ```
 * node scripts/check-quiz.mjs vietnam
 * ```
 * で答えの漏れ・4言語の混入と欠け・正解の位置の偏りを確認すること
 * (焼き上がり前提の検査なので、下書き段階では使い捨てcontent.jsonが必要)。
 */
function t(source) {
  const parts = source.split("|");
  if (parts.length !== 4) {
    throw new Error(`4言語(en|es|fr|ja)で書いてください: ${source.slice(0, 60)}…`);
  }
  const [en, es, fr, ja] = parts;
  return { en, es, fr, ja };
}

/** 1問を組み立てる。`o` は選択肢の配列、`a` は正解の添字。 */
function q(difficulty, question, options, a, fact) {
  return { difficulty, q: t(question), o: options.map(t), a, f: t(fact) };
}

